`timescale 1ns/1ps
module tb_l5_prefill_count_controller;
 logic clk;/* verilator lint_off SYNCASYNCNET */logic rst_n;/* verilator lint_on SYNCASYNCNET */logic start,cr,ed,cv,lv,score,done,err;logic[10:0]seqin,seqout;logic[4:0]op;logic[2:0]eng;logic[31:0]work,steps,cmds,mt,rope,dot,online,recip,norm,silu,prod,sc;logic[63:0]h128,h384,h1024;
 always #5 clk=~clk;l5_prefill_count_controller dut(.clk_i(clk),.rst_ni(rst_n),.start_i(start),.command_ready_i(cr),.engine_done_i(ed),.sequence_length_i(seqin),.command_valid_o(cv),.measured_latency_valid_o(lv),.score_matrix_o(score),.done_o(done),.config_error_o(err),.sequence_length_o(seqout),.operation_o(op),.engine_o(eng),.work_items_o(work),.matrix_steps_o(steps),.commands_issued_o(cmds),.matrix_steps_total_o(mt),.rope_pairs_total_o(rope),.dot_operations_total_o(dot),.online_updates_total_o(online),.reciprocals_total_o(recip),.normalization_chunks_total_o(norm),.silu_scalars_total_o(silu),.product_chunks_total_o(prod),.score_matrix_commands_o(sc));
 function automatic[63:0]hh(input[63:0]h,input[4:0]o,input[31:0]w,s);logic[63:0]x;begin x=(h^{59'd0,o})*64'h100000001b3;x=(x^{32'd0,w})*64'h100000001b3;x=(x^{32'd0,s})*64'h100000001b3;hh=x;end endfunction
 task automatic run(input[10:0]seq,output[63:0]hash);begin rst_n=0;start=0;cr=0;ed=0;seqin=seq;hash=64'hcbf29ce484222325;repeat(3)@(posedge clk);rst_n=1;@(negedge clk);start=1;@(posedge clk);@(negedge clk);start=0;for(int i=0;i<24;i++)begin do@(negedge clk);while(!cv);if(lv||score||err||seqout!=seq)$fatal(1,"unified prefill command");hash=hh(hash,op,work,steps);cr=1;@(posedge clk);@(negedge clk);cr=0;ed=1;@(posedge clk);@(negedge clk);ed=0;end if(!done||cmds!=24||sc!=0)$fatal(1,"unified common totals");if(seq==128)begin if(mt!=11698176||rope!=114688||dot!=99072||online!=99072||recip!=1536||norm!=12288||silu!=1146880||prod!=71680)$fatal(1,"unified128");end else if(seq==384)begin if(mt!=35094528||rope!=344064||dot!=887040||online!=887040||recip!=4608||norm!=36864||silu!=3440640||prod!=215040)$fatal(1,"unified384");end else begin if(mt!=93585408||rope!=917504||dot!=6297600||online!=6297600||recip!=12288||norm!=98304||silu!=9175040||prod!=573440)$fatal(1,"unified1024");end end endtask
 initial begin clk=0;run(128,h128);run(384,h384);run(1024,h1024);rst_n=0;seqin=256;repeat(3)@(posedge clk);rst_n=1;@(negedge clk);start=1;@(posedge clk);@(negedge clk);start=0;@(posedge clk);if(!done||!err||cmds!=0)$fatal(1,"unified invalid");$display("L5_UNIFIED_PREFILL_COUNT_CONTROLLER_PASS same_binary=1 seq128_steps=11698176 seq384_steps=35094528 seq1024_steps=93585408 score_matrix_commands=0 hash128=%016h hash384=%016h hash1024=%016h invalid256_rejected=1",h128,h384,h1024);$finish;end
endmodule
